lib.sha256.argtypes=[ctypes.c_void_p, ctypes.c_size_t, ctypes.c_void_p]
data = random.randbytes(20000*1024)
buf = ctypes.create_string_buffer(data)
out = ctypes.create_string_buffer(32)
for _ in range(5): lib.sha256(buf, len(data), out)
for _ in range(5): hashlib.sha256(data).digest()
def c():
    lib.sha256(buf, len(data), out)
def hl():
    hashlib.sha256(data).digest()
for name,fn in [('C',c),('hashlib',hl)]:
    ts=[]
    for _ in range(30):
        t0=time.perf_counter_ns(); fn(); ts.append(time.perf_counter_ns()-t0)
    print(name, min(ts)/1e9, statistics.median(ts)/1e9)
""}

